// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    address owner;

    function setUp() public { c = new MyContract(); owner = address(this); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        uint256 bounded = bound(amount, 0, 1 ether);

        vm.deal(address(c), bounded);

        uint256 before = address(c).balance;

        bool ok;
        try c.sendTo(receiver, bounded) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == before - bounded);
        } else {
            assertTrue(address(c).balance <= before);
        }
    }
}
